    let sql2 = `
      SELECT id, name, email, phone, role 
      FROM core_users 
      WHERE (LOWER(email) LIKE $1 OR LOWER(name) LIKE $1 OR LOWER(phone) LIKE $1)
    `;
    const params = [`%${q3}%`];
    if (excludeUserId) {
      params.push(excludeUserId);
      sql2 += ` AND id != $${params.length}`;
    }
    sql2 += ` ORDER BY name ASC LIMIT 5`;
    try {
      const res = await query(sql2, params);
      return res.rows;
    } catch (e5) {
      console.warn("searchRecipients error:", e5?.message);
      return [];
    }
