var streamLocalChunkedMedia = (req, res) => {
  const filename = req.params.filename || req.params[0];
  if (!filename) return res.status(400).send("Filename required");
  const safeName = path4.basename(filename);
  const ext = path4.extname(safeName).toLowerCase();
  const allowedExtensions = [
    ".mp4",
    ".webm",
    ".ogg",
    ".mp3",
    ".wav",
    ".m4a",
    ".aac",
    ".jpg",
    ".jpeg",
    ".png",
    ".gif",
    ".webp",
    ".pdf",
    ".zip"
  ];
  if (!allowedExtensions.includes(ext)) {
    return res.status(403).send("Forbidden: file type not permitted for download");
  }
  const possibleDirs = [
    path4.join(process.cwd(), "public", "uploads"),
    path4.join(process.cwd(), "uploads"),
    path4.join(process.cwd(), "public", "uploads", "media")
  ];
  let filePath = "";
  for (const dir of possibleDirs) {
    const candidate = path4.join(dir, safeName);
    const resolvedCandidate = path4.resolve(candidate);
    const resolvedDir = path4.resolve(dir);
    if (resolvedCandidate.startsWith(resolvedDir + path4.sep) && fs5.existsSync(resolvedCandidate)) {
      filePath = resolvedCandidate;
      break;
    }
  }
  if (!filePath || !fs5.existsSync(filePath)) {
    return res.status(404).send("Media file not found");
  }
  res.setHeader("X-Content-Type-Options", "nosniff");
  const stat = fs5.statSync(filePath);
  const fileSize = stat.size;
  const range2 = req.headers.range;
  const mimeMap = {
    ".mp4": "video/mp4",
    ".webm": "video/webm",
    ".ogg": "video/ogg",
    ".mp3": "audio/mpeg",
    ".wav": "audio/wav",
    ".m4a": "audio/mp4",
    ".aac": "audio/aac",
    ".jpg": "image/jpeg",
    ".jpeg": "image/jpeg",
    ".png": "image/png",
    ".gif": "image/gif",
    ".webp": "image/webp"
  };
  const contentType = mimeMap[ext] || "application/octet-stream";
  if (range2) {
    const parts = range2.replace(/bytes=/, "").split("-");
    const start = parseInt(parts[0], 10);
    const chunkSizeLimit = 1024 * 1024;
    const requestedEnd = parts[1] ? parseInt(parts[1], 10) : fileSize - 1;
    const end = Math.min(requestedEnd, start + chunkSizeLimit - 1, fileSize - 1);
    const chunksize = end - start + 1;
    const file = fs5.createReadStream(filePath, { start, end });
    res.writeHead(206, {
      "Content-Range": `bytes ${start}-${end}/${fileSize}`,
      "Accept-Ranges": "bytes",
      "Content-Length": chunksize,
      "Content-Type": contentType,
      "Cache-Control": "public, max-age=86400",
      "X-Content-Type-Options": "nosniff"
    });
    file.pipe(res);
  } else {
    if (ext === ".mp4" || ext === ".webm" || ext === ".mp3" || ext === ".m4a") {
      const initialChunkSize = Math.min(fileSize, 512 * 1024);
      const file = fs5.createReadStream(filePath, { start: 0, end: initialChunkSize - 1 });
      res.writeHead(206, {
        "Content-Range": `bytes 0-${initialChunkSize - 1}/${fileSize}`,
        "Accept-Ranges": "bytes",
        "Content-Length": initialChunkSize,
        "Content-Type": contentType,
        "Cache-Control": "public, max-age=86400"
      });
      file.pipe(res);
    } else {
      res.writeHead(200, {
        "Content-Length": fileSize,
        "Content-Type": contentType,
        "Accept-Ranges": "bytes",
        "Cache-Control": "public, max-age=86400"
      });
      fs5.createReadStream(filePath).pipe(res);
    }
  }
};
