app.get("/api/admin/creators/monetization", authenticateToken, requireAdminRole, async (req, res) => {
  try {
    await query(`ALTER TABLE core_users ADD COLUMN IF NOT EXISTS monetization_status VARCHAR(32) DEFAULT 'auto';`).catch(() => {
    });
    await query(`ALTER TABLE core_users ADD COLUMN IF NOT EXISTS monetization_warning TEXT;`).catch(() => {
    });
    const reqHoursStr = await getSystemSetting4("monetization_required_watch_hours", "300");
    const reqSubsStr = await getSystemSetting4("monetization_required_subscribers", "30");
    const reqHours = Number(reqHoursStr) || 300;
    const reqSubs = Number(reqSubsStr) || 30;
    const creatorsRes = await query(`
      SELECT 
        u.id, 
        u.name, 
        u.email, 
        u.channel_name, 
        u.phone,
        u.role,
        COALESCE(u.monetization_status, 'auto') as monetization_status,
        u.monetization_warning,
        COALESCE(v.video_count, 0) as video_count,
        COALESCE(v.video_views_seconds, 0) as video_views_seconds,
        COALESCE(w.total_seconds, 0) as total_watch_seconds,
        COALESCE(s.subscriber_count, 0) as subscriber_count,
        COALESCE(wl.total_earnings, 0) as total_earnings
      FROM core_users u
      LEFT JOIN (
        SELECT 
          user_id, 
          COUNT(*) as video_count,
          SUM(COALESCE(views, 0) * COALESCE(duration, 180)) as video_views_seconds
        FROM user_videos GROUP BY user_id
      ) v ON u.id = v.user_id
      LEFT JOIN (
        SELECT creator_id, SUM(duration_seconds) as total_seconds FROM video_watch_time GROUP BY creator_id
      ) w ON (u.id = w.creator_id OR (u.channel_name IS NOT NULL AND u.channel_name = w.creator_id))
      LEFT JOIN (
        SELECT creator_id, COUNT(*) as subscriber_count FROM creator_subscribers GROUP BY creator_id
      ) s ON (u.id = s.creator_id OR (u.channel_name IS NOT NULL AND u.channel_name = s.creator_id))
      LEFT JOIN core_wallets wl ON u.id = wl.user_id
      WHERE u.role != 'superadmin' OR u.channel_name IS NOT NULL
      ORDER BY total_watch_seconds DESC, u.created_at DESC
      LIMIT 100
    `);
    const creators = creatorsRes.rows.map((r5) => {
      const totalSec = (Number(r5.total_watch_seconds) || 0) + (Number(r5.video_views_seconds) || 0);
      const rawHours = totalSec / 3600;
      let watchHours = 0;
      if (rawHours > 0 && rawHours < 0.1) {
        watchHours = Math.round(rawHours * 1e3) / 1e3;
      } else {
        watchHours = Math.round(rawHours * 10) / 10;
      }
      const subs = Number(r5.subscriber_count) || 0;
      const totalEarnings = Number(r5.total_earnings) || 0;
      let status = r5.monetization_status;
      let isMonetized = false;
      if (status === "active") {
        isMonetized = true;
      } else if (status === "paused" || status === "suspended") {
        isMonetized = false;
      } else {
        isMonetized = watchHours >= reqHours && subs >= reqSubs;
        status = isMonetized ? "active" : "not_monetized";
      }
      return {
        id: r5.id,
        name: r5.name,
        email: r5.email,
        channel_name: r5.channel_name || `${r5.name}'s Studio`,
        channelName: r5.channel_name || `${r5.name}'s Studio`,
        phone: r5.phone,
        video_count: Number(r5.video_count) || 0,
        videoCount: Number(r5.video_count) || 0,
        watch_hours: watchHours,
        watchHours,
        subscribers_count: subs,
        subscribers: subs,
        total_earnings: totalEarnings,
        monetization_status: status,
        monetizationStatus: status,
        monetization_warning: r5.monetization_warning,
        monetizationWarning: r5.monetization_warning,
        is_monetized: isMonetized,
        isMonetized
      };
    });
    return res.json({ success: true, creators, requiredWatchHours: reqHours, requiredSubscribers: reqSubs });
  } catch (err) {
    return res.status(500).json({ error: err.message, creators: [] });
  }
});
