    const finalBudget = dailyBudget !== void 0 || daily_budget !== void 0 ? Number(dailyBudget ?? daily_budget) : null;
    const finalCpm = cpmBid !== void 0 || cpm_bid !== void 0 ? Number(cpmBid ?? cpm_bid) : null;
