var handleGameRefund = async (req, res) => {
  try {
    const userId = req.user?.id;
    if (!userId) return res.status(401).json({ error: "Unauthorized" });
    let roomIdToCancel = null;
    try {
      roomIdToCancel = req.body?.roomId || null;
    } catch {
    }
    let sql2 = `SELECT * FROM game_rooms WHERE (player1_id = $1 OR player2_id = $1) AND status IN ('ACTIVE', 'WAITING') AND p1_score = 0 AND p2_score = 0 AND current_accumulated = 0`;
    const params = [userId];
    if (roomIdToCancel) {
      params.push(roomIdToCancel);
      sql2 += ` AND id = $${params.length}`;
    }
    const activeRooms = await query(sql2, params);
    let totalRefunded = 0;
    for (const r5 of activeRooms.rows) {
      const stake = Number(r5.stake || 0);
      if (stake > 0) {
        const cancelRes = await query(
          `UPDATE game_rooms SET status = 'CANCELLED' 
           WHERE id = $1 AND status IN ('ACTIVE', 'WAITING') AND p1_score = 0 AND p2_score = 0 AND current_accumulated = 0 
           RETURNING *`,
          [r5.id]
        );
        if (cancelRes.rowCount > 0) {
          await WalletService.credit(userId, stake, "game", "refund", "RollDice Game Cancelled / Refunded", r5.id);
          totalRefunded += stake;
        }
      }
    }
    const curWallet = await WalletService.getOrCreateWallet(userId);
    return res.json({
      success: true,
      refundedAmount: totalRefunded,
      newBalance: Number(curWallet.balance)
    });
  } catch (err) {
    return res.status(500).json({ error: err.message || "Refund failed" });
  }
};
app.post("/api/game/refund", authenticateToken, handleGameRefund);
