app.post("/api/admin/stations/test-stream", authenticateToken, requireStaffRole, async (req, res) => {
  const { url: url2 } = req.body;
  if (!url2) return res.status(400).json({ error: "Stream URL is required." });
  const startTime = Date.now();
  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 6e3);
    const upstream = await fetch(url2, {
      method: "GET",
      headers: { Range: "bytes=0-1024" },
      signal: controller.signal
    });
    clearTimeout(timeout);
    const latencyMs = Date.now() - startTime;
    const contentType = upstream.headers.get("content-type") || "Unknown";
    const isReachable = upstream.ok || upstream.status === 206 || upstream.status === 200;
    let detectedFormat = "Unknown";
    if (url2.includes(".m3u8") || contentType.includes("mpegurl") || contentType.includes("application/x-mpegURL")) {
      detectedFormat = "HLS Adaptive Bitrate (m3u8)";
    } else if (contentType.includes("audio/mpeg") || url2.endsWith(".mp3")) {
      detectedFormat = "Icecast / Shoutcast MP3 Audio";
    } else if (contentType.includes("audio/aac") || contentType.includes("audio/aacp")) {
      detectedFormat = "AAC Audio Stream";
    } else if (contentType.includes("audio")) {
      detectedFormat = "Standard HTML5 Audio";
    }
    return res.json({
      reachable: isReachable,
      status: upstream.status,
      statusText: upstream.statusText,
      contentType,
      detectedFormat,
      latencyMs,
      message: isReachable ? "\u2713 Stream server online and responding" : `\u26A0\uFE0F Stream responded with HTTP status ${upstream.status}`
    });
  } catch (err) {
    const latencyMs = Date.now() - startTime;
    return res.json({
      reachable: false,
      status: 0,
      contentType: "N/A",
      detectedFormat: "Unknown",
      latencyMs,
      error: err.message || "Stream connection failed or timed out.",
      message: "\u2715 Stream unreachable or server timed out."
    });
  }
});
app.get("/api/admin/users/:id/details", authenticateToken, requireAdminRole, async (req, res) => {
  try {
    const { id } = req.params;
    const userRes = await query(`
      SELECT u.id, u.email, u.name, u.role, u.phone, u.preferred_language, u.is_verified, u.created_at,
             w.balance as wallet_balance, w.bonus_balance, w.pending_balance, w.currency,
             w.total_earnings, w.total_withdrawn, w.total_bonus_received
      FROM core_users u
      LEFT JOIN core_wallets w ON u.id = w.user_id
      WHERE u.id = $1
    `, [id]);
    if (userRes.rowCount === 0) {
      return res.status(404).json({ error: "User not found." });
    }
    const userData = userRes.rows[0];
    const txRes = await query(`
      SELECT id, module, type, amount, fee, currency, status, reference, description, metadata, created_at
      FROM core_wallet_transactions
      WHERE user_id = $1
      ORDER BY created_at DESC
      LIMIT 100
    `, [id]).catch(() => ({ rows: [] }));
    const depRes = await query(`
      SELECT tx_ref, currency, original_amount, converted_rwf, status, flw_ref, admin_note, created_at
      FROM pending_flutterwave_deposits
      WHERE user_id = $1
      ORDER BY created_at DESC
      LIMIT 100
    `, [id]).catch(() => ({ rows: [] }));
    const monRes = await query(`
      SELECT * FROM user_monetization_settings WHERE user_id = $1
    `, [id]).catch(() => ({ rows: [] }));
    const monetization = monRes.rows[0] || {
      is_monetized: false,
      status: "standard",
      watch_hours: 0,
      subscribers: 0,
      total_earnings: 0
    };
    const videosRes = await query(`
      SELECT id, title, description, category, price, is_paid, views, watch_hours,
             revenue_generated, thumbnail_url, video_url, created_at
      FROM user_videos
      WHERE user_id = $1
      ORDER BY created_at DESC
      LIMIT 100
    `, [id]).catch(() => ({ rows: [] }));
    return res.json({
      user: userData,
      wallet: {
        balance: Number(userData.wallet_balance || 0),
        bonus_balance: Number(userData.bonus_balance || 0),
        pending_balance: Number(userData.pending_balance || 0),
        currency: userData.currency || "RWF",
        total_earnings: Number(userData.total_earnings || 0),
        total_withdrawn: Number(userData.total_withdrawn || 0),
        total_bonus_received: Number(userData.total_bonus_received || 0)
      },
      transactions: txRes.rows,
      deposits: depRes.rows,
      monetization,
      videos: videosRes.rows
    });
  } catch (err) {
    return res.status(500).json({ error: err.message });
  }
});
app.post("/api/admin/users/:id/adjust-wallet", authenticateToken, requireAdminRole, async (req, res) => {
  try {
    const { id } = req.params;
    const { amount, type, note } = req.body;
    const numAmount = Math.abs(Number(amount));
    if (!numAmount || numAmount <= 0) {
      return res.status(400).json({ error: "Valid positive adjustment amount is required." });
    }
    if (type !== "credit" && type !== "deduct") {
      return res.status(400).json({ error: 'Adjustment type must be "credit" or "deduct".' });
    }
    const adminEmail = req.user?.email || "admin@benix.space";
    let result;
    if (type === "credit") {
      result = await WalletService.credit(
        id,
        numAmount,
        "wallet",
        "admin_credit",
        `Admin Wallet Credit: +${numAmount.toLocaleString()} RWF (${note || "Manual topup by admin " + adminEmail})`,
        `tx_adm_cr_${Date.now()}`
      );
    } else {
      result = await WalletService.debit(
        id,
        numAmount,
        "wallet",
        "admin_deduct",
        `Admin Wallet Deduction: -${numAmount.toLocaleString()} RWF (${note || "Manual adjustment by admin " + adminEmail})`,
        `tx_adm_db_${Date.now()}`
      );
    }
    return res.json({
      success: true,
      message: `Successfully ${type === "credit" ? "credited" : "deducted"} ${numAmount.toLocaleString()} RWF.`,
      newBalance: result.newBalance
    });
  } catch (err) {
    return res.status(500).json({ error: err.message });
  }
});
